// Shallow check. Costs nothing — no LLM calls, just the n8n API.
const EXPECTED = ['1 — Jarvis Hub', '2 — Producers', '3 — Researchers', '4 — Watchdog'];

const wfResp = $('Which Are Active?').first().json;
const exResp = $('Anything Failing?').first().json;

const problems = [];
let activeNames = [];

// If the API itself is unreachable we know nothing — say that, rather than
// reporting a green system on the strength of a failed request.
if (!wfResp || wfResp.error || !Array.isArray(wfResp.data)) {
  problems.push('Cannot reach the n8n API. Check the host URL and the API key credential.');
} else {
  activeNames = wfResp.data.map(w => w.name);
  for (const expected of EXPECTED) {
    if (!activeNames.some(n => n.startsWith(expected.split(' —')[0]))) {
      problems.push(`Workflow "${expected}" is not active.`);
    }
  }
}

// Only count failures since the last check, so one old error doesn't stay red forever.
const store = $getWorkflowStaticData('global');
const since = store.lastCheck ? new Date(store.lastCheck) : new Date(Date.now() - 15 * 60 * 1000);
let recentFailures = [];

if (exResp && Array.isArray(exResp.data)) {
  recentFailures = exResp.data
    .filter(e => new Date(e.startedAt) > since)
    .map(e => ({ workflow: e.workflowData?.name || e.workflowId, at: e.startedAt }));
  for (const f of recentFailures) {
    problems.push(`"${f.workflow}" failed at ${f.at}.`);
  }
}

const healthy = problems.length === 0;

store.lastCheck = new Date().toISOString();
store.healthy = healthy;
store.problems = problems;
store.activeCount = activeNames.length;
store.consecutiveFailures = healthy ? 0 : (store.consecutiveFailures || 0) + 1;

// Spoken summary — the hub reads this aloud, so no markdown and no URLs.
store.spoken = healthy
  ? `Everything is running. ${activeNames.length} workflows active, nothing failed since the last check.`
  : `${problems.length} problem${problems.length === 1 ? '' : 's'}. ${problems[0]}`;

return [{ json: { healthy, problems, recentFailures, activeNames, spoken: store.spoken, consecutiveFailures: store.consecutiveFailures, checkedAt: store.lastCheck } }];

