// Deep probe. Actually calls each team end to end, once a day.
// A team that returns HTTP 200 but empty output is broken in the way that
// matters most, so check for real content rather than just a status code.
const probes = [
  { team: 'producers',   raw: $('Probe Producers').first().json },
  { team: 'researchers', raw: $('Probe Researchers').first().json },
  { team: 'hub',         raw: $('Probe Hub').first().json }
];

const results = probes.map(p => {
  const body = p.raw || {};
  const text = JSON.stringify(body);
  const errored = !!body.error || text.length < 10;
  return {
    team: p.team,
    ok: !errored,
    detail: errored ? (body.error?.message || body.message || 'empty or malformed response') : 'responded'
  };
});

const failed = results.filter(r => !r.ok);
const store = $getWorkflowStaticData('global');

store.lastDeepProbe = new Date().toISOString();
store.deepProbeResults = results;
store.deepProbeHealthy = failed.length === 0;

const spoken = failed.length === 0
  ? 'Deep probe passed. All three teams responded.'
  : `Deep probe failed for ${failed.map(f => f.team).join(' and ')}.`;

store.deepProbeSpoken = spoken;

return [{ json: { results, failed, healthy: failed.length === 0, spoken, at: store.lastDeepProbe } }];

// Answers the hub's watchdog tool from stored state — no probing on demand,
// so asking 'is everything working' is instant and free.
const store = $getWorkflowStaticData('global');

if (!store.lastCheck) {
  return [{ json: {
    spoken: 'The watchdog has not run yet. It checks every fifteen minutes, so give it a moment.',
    healthy: null,
    everRun: false
  } }];
}

const ageMin = Math.round((Date.now() - new Date(store.lastCheck)) / 60000);
const stale = ageMin > 45;

let spoken = store.spoken || 'No verdict recorded.';
if (stale) {
  spoken = `Careful — the last check was ${ageMin} minutes ago, so this may be out of date. ${spoken}`;
}
if (store.deepProbeSpoken) {
  spoken += ' ' + store.deepProbeSpoken;
}

return [{ json: {
  spoken,
  healthy: store.healthy,
  problems: store.problems || [],
  activeCount: store.activeCount,
  lastCheck: store.lastCheck,
  lastCheckAgeMinutes: ageMin,
  stale,
  lastDeepProbe: store.lastDeepProbe || null,
  deepProbeResults: store.deepProbeResults || [],
  everRun: true
} }];
